function ITEMBLUE_CheckTriThuc(nItemCount)
    local tbremove = {}
    local nTotalTriThuc = 0
    for k=1, nItemCount do
        local itemidx = GetGiveItemUnit(k)
        local nPar, nID, nType = GetItemProp(itemidx)
        if (nPar == 4) and (nID == 2054) then
            local nStack = GetItemStackCount(itemidx)
            if (nStack < 1) then nStack = 1 end 
            nTotalTriThuc = nTotalTriThuc + nStack
            tinsert(tbremove, itemidx)
        else
            Say("VËt phÈm <color=yellow>"..GetItemName(itemidx).."<color> kh«ng ph¶i TuyÖt §Ønh Tri Thøc!", 0)
            return
        end
    end
    if nTotalTriThuc > 0 then
        for k=1, getn(tbremove) do
            RemoveItemByIndex(tbremove[k])
        end
        local nOldTask = gTask(ITEMBLUE_TSKID_COUNT)
        sTask(ITEMBLUE_TSKID_COUNT, nOldTask + nTotalTriThuc)
        Msg2Player("B¹n ®· ®æi thµnh c«ng "..nTotalTriThuc.." TuyÖt §Ønh Tri Thøc lÊy "..nTotalTriThuc.." lÇn chÕ t¹o.")
    else
        Say("Ng­¬i ch­a bá TuyÖt §Ønh Tri Thøc vµo!", 0)
    end
end